export function CalendarOverlay({
  primaryLabel = "{{primaryLabel}}",
  secondaryLabel = "{{secondaryLabel}}",
  mode = "{{mode}}",
  primaryAccent = "{{primaryAccent}}",
  secondaryAccent = "{{secondaryAccent}}",
}) {
  const side = mode === "Side by side";
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 420, padding: 18, borderRadius: 12, boxSizing: "border-box" }}>
      <div style={{ display: "flex", gap: 16, marginBottom: 14 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 6, fontWeight: 600 }}><span style={{ width: 9, height: 9, borderRadius: 999, display: "inline-block", background: primaryAccent }} />{primaryLabel}</span>
        <span style={{ display: "flex", alignItems: "center", gap: 6, fontWeight: 600 }}><span style={{ width: 9, height: 9, borderRadius: 999, display: "inline-block", background: secondaryAccent }} />{secondaryLabel}</span>
      </div>
      <div style={{ position: "relative", height: 64, background: "#24143010", borderRadius: 8 }}>
        <div style={{ position: "absolute", top: 8, height: 24, left: side ? "2%" : "4%", width: side ? "46%" : "44%", borderRadius: 6, padding: "3px 8px", fontWeight: 600, color: "#14351f", boxSizing: "border-box", whiteSpace: "nowrap", overflow: "hidden", background: primaryAccent }}>9&ndash;10am Standup</div>
        <div style={{ position: "absolute", top: side ? 8 : 34, height: 24, left: side ? "52%" : "24%", width: side ? "46%" : "44%", borderRadius: 6, padding: "3px 8px", fontWeight: 600, color: "#14351f", boxSizing: "border-box", whiteSpace: "nowrap", overflow: "hidden", background: secondaryAccent }}>9:30&ndash;11am Planning</div>
      </div>
    </div>
  );
}
